We have by definition and \Cref{Dirichlet-kernel}  egin{equation} L_Ng(x)=  rac 1N\sum_{n=0}^{N-1} \int_0^{2\pi} e^{-i(N+n)x} K_{N+n}(x-y) e^{i(N+n)y}g(y) \, dy \, .\end{equation} This is of the form \eqref{lthroughlprime} with the continuous function  egin{equation} {L'}(x)=  rac 1N\sum_{n=0}^{N-1} K_{N+n}(x) e^{-i(N+n)x}\, . \end{equation} With \eqref{eqksumexp} of \Cref{Dirichlet-kernel} we have $|K_N(x)|\le 2N+1$ for every $x$ and thus  egin{equation} |{L'}(x)|\le  rac 1N\sum_{n=0}^{N-1} (2N+2n+1) \le 4N\le 2^3 r^{-1}\, . \end{equation} Therefore, for $|x|\in [0, r)\cup (1, \pi]$, we have  egin{equation} \left|L'(x)-\mathbf{1}_{\{y:\, r<|y|<1\}}(x)\kappa(x)ight|=|L'(x)|\leq 2^{3} r^{-1}. \end{equation} This proves \eqref{eqdifflhil} for $|x|\in [0, r)$ since $k_r(x)=r^{-1}$ in this case. For $e^{ix}
eq 1$ one may use the expression \eqref{eqksumhil} for $K_N$ in \Cref{Dirichlet-kernel} to obtain  egin{equation*} {L'}(x)=  rac 1N\sum_{n=0}^{N-1} \left( rac{e^{i(N+n)x}}{1-e^{-ix}} + rac {e^{-i(N+n)x}}{1-e^{ix}}ight) e^{i(N+n)x} \end{equation*}  egin{equation*} =  rac 1N\sum_{n=0}^{N-1} \left( rac{e^{i2(N+n)x}}{1-e^{-ix}} + rac {1}{1-e^{ix}}ight) \end{equation*}  egin{equation} =  rac{1}{1-e^{ix}} +  rac 1N  rac {e^{i2Nx}}{1-e^{-ix}} \sum_{n=0}^{N-1} {e^{i2nx}} \end{equation} and thus  egin{equation} {L'}(x) -\mathbf{1}_{\{y:\, r<|y|<1\}}\kappa(x)=L''(x)+  rac{1-\mathbf{1}_{{\{y:\, r<|y|<1\}}}(x)(1-|x|)}{1-e^{ix}}, \end{equation} where $$L''(x):= rac 1N  rac {e^{i2Nx}}{1-e^{-ix}} \sum_{n=0}^{N-1} {e^{i2nx}}.$$ For $x\in [-\pi, r]\cup [r, \pi]$, we have using \Cref{lower-secant-bound} that  egin{equation*} \left| rac{1-\mathbf{1}_{{\{y:\, r<|y|<1\}}}(x)(1-|x|)}{1-e^{ix}} ight|=\left| rac{\min(|x|, 1)}{1-e^{ix}} ight|\leq  rac{2\min(|x|, 1)}{|x|} \end{equation*}  egin{equation} \leq 2\cdot 1\leq 2 k_r(x). \end{equation} Next, we need to estimate $L''(x)$. If the real part of $e^{ix}$ is negative, we have  egin{equation} 1\le |1-e^{-ix}|\le 2\, . \end{equation} and hence  egin{equation} |L''(x)|\le  rac 1N \sum_{n=0}^{N-1} 1=1\le 1+ rac r{|1-e^{ix}|^2}\, . \end{equation} If the real part of $e^{ix}$ is positive and in particular while still $e^{ix}
eq \pm 1$, then we have by telescoping  egin{equation} (1-e^{2ix}) \sum_{n=0}^{N-1} {e^{i2nx}}=1-e^{i2Nx}\, . \end{equation} As $e^{2ix}
eq 1$, we may divide by $1-e^{2ix}$ and insert this into \eqref{eqhil3} to obtain  egin{equation} L''(x)=  rac 1N  rac {e^{i2Nx}}{1-e^{-ix}}  rac{1-e^{i2Nx}}{1-e^{2ix}}\, . \end{equation} Hence, using the nonnegativity of the real part of $e^{ix}$  egin{equation*} |L''(x)| \le  rac 2 N  rac {1}{|1-e^{ix}|}  rac{1}{|1-e^{2ix}|} \end{equation*}  egin{equation} =  rac 2 N  rac {1}{|1-e^{ix}|^2}  rac{1}{|1+e^{ix}|}\le  rac {2r}{|1-e^{ix}|^2}\le 2 \left(1+ rac {r}{|1-e^{ix}|^2}ight) \end{equation} Moreover, for $|x| \in [r, \pi]$, one checks easily that  egin{equation*} 1+ rac {r}{|1-e^{ix}|^2} \leq 5 k_r(x). \end{equation*} Therefore,~\eqref{eqhil12} and~\eqref{eqhil11} show that, in this range of $x$,  egin{equation*} |L''(x)| \le 10 k_r(x). \end{equation*} Together with~\eqref{eq-diffzero2}, this prove \eqref{eqdifflhil} for $|x| \in [r, \pi]$. As the range $|x| \in [0,r)$ is covered by~\eqref{eqdiffzero}, this completes the proof of the lemma.
